// Tests for the medical record (src/medrecord.js): the sections it builds from what the crew screen holds, newest
// first, each item linked to where it came from; only the signed-in person's own records; private parts marked; the
// sections a full medical card holds but this prototype does not, with their reason; the real Inspiration4 blood
// draws against their lab ranges; old saved events still readable. Pure functions, no browser needed.
// Run: node --test tests/medrecord.test.js. Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createMachine } from '../src/engine.js';
import { CELLS, CREW, SHIP, realPeople } from '../src/config.js';
import { INSPIRATION4 } from '../src/inspiration4.js';
import { exampleFlight, MISSION } from '../src/demo-crew.js';
import { CONNECTIONS } from '../src/integrations.js';
import { PRIVATE_NOTE } from '../src/quicklog.js';
import { LEVEL, VITAL_SIGNS } from '../src/state-levels.js';
import { TIPS } from '../src/tips.js';
import {
  buildRecord, valueWords, sourceWords, readingVerdict, topicWords, cycleWords, checkinDays, messageTitle, lineWords, drawTime, drawWords,
  NOT_HELD, NOT_HELD_TEXT, NOT_HELD_CONNECTION, SECTION_ORDER, SECTION_INFO, RECORD_SOURCES, RECORD_RULES, I4_DATES,
} from '../src/medrecord.js';

const REAL = realPeople(INSPIRATION4.subjects);
const NOW = new Date('2026-11-15T12:00:00Z');
const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
const ago = (h) => new Date(NOW.getTime() - h * HOUR).toISOString();
const tom = CREW.find((p) => p.id === 'crew-1');
const elly = CREW.find((p) => p.id === 'crew-2');
const state = { aiWorks: true, doctorOnBoard: false, linkToEarth: true };

const machineWith = (readings = []) => {
  const m = createMachine({ cells: CELLS, crew: [...CREW, SHIP, ...REAL], state });
  for (const r of [...readings].sort((a, b) => Date.parse(a.time) - Date.parse(b.time))) m.receive(r);
  return m;
};
const record = (person, machine, extra = {}) => buildRecord({ person, history: (id, ind) => machine.history(id, ind), now: NOW, storeKind: 'server', ship: { linkToEarth: true }, ...extra });
const section = (rec, id) => rec.sections.find((s) => s.id === id);
const isNewestFirst = (items) => items.every((x, i) => i === 0 || Date.parse(items[i - 1].time) >= Date.parse(x.time));

// The example flight as the crew screen builds it (crew.js rebuild), up to the example's own "today".
const flightMachine = () => {
  const m = createMachine({ cells: CELLS, crew: [...CREW, SHIP, ...REAL], state });
  for (const ev of exampleFlight(CREW).sort((a, b) => Date.parse(a.time) - Date.parse(b.time))) if (ev.kind === 'reading') m.receive({ ...ev.reading, person: ev.person, time: ev.time, example: true });
  return m;
};

test('the sections come in a fixed order, each with its count, and the measures show their latest reading, newest first', () => {
  const m = flightMachine();
  const rec = buildRecord({ person: elly, history: (id, ind) => m.history(id, ind), now: new Date(MISSION.today), mission: { ...MISSION, example: true }, flightDay: { words: 'Flight day 167' }, storeKind: 'server' });
  assert.deepEqual(rec.sections.map((s) => s.id), SECTION_ORDER.filter((id) => rec.sections.some((s) => s.id === id)));
  assert.deepEqual(rec.sections.map((s) => s.id), ['vitals', 'measures', 'labs', 'eyes', 'medicines', 'symptoms', 'alerts', 'encounters', 'mind', 'cycle', 'documents']);
  for (const s of rec.sections) {
    assert.equal(s.count, s.items.length, s.id);
    assert.equal(s.title, SECTION_INFO[s.id].title);
    if (s.items.length && s.items[0].time) assert.ok(isNewestFirst(s.items), `${s.id} is newest first`);
  }
  const vitals = section(rec, 'vitals');
  assert.deepEqual(vitals.items.map((x) => x.indicator).sort(), [...VITAL_SIGNS].sort());
  for (const row of vitals.items) {
    const list = m.history(elly.id, row.indicator);
    assert.equal(row.count, list.length);
    assert.equal(row.time, list[list.length - 1].time.toISOString());
    assert.equal(row.source, 'Made-up example data');
    assert.deepEqual(row.link, { to: 'measure', indicator: row.indicator });
    assert.ok(row.value && row.unit, row.indicator);
  }
  const bp = vitals.items.find((x) => x.indicator === 'bp');
  assert.match(bp.value, /^\d+\/\d+$/);
  assert.equal(rec.header.name, 'Elly');
  assert.match(rec.header.kindText, /made-up person/);
  const facts = Object.fromEntries(rec.header.facts);
  assert.match(facts.Mission, /^Example flight \(made up\): launch \d+ \w+ 2026, landing \d+ \w+ 2026\. Flight day 167$/);
  assert.match(facts['In this record'], /readings, all of them made-up example data/);
  assert.match(facts.Record, /^crew-2\. Kept on the station computer/);
});

test('only the signed-in person: crewmates, the ship and anyone else stay out, and the ship has no record', () => {
  const m = machineWith([
    { source: 'oximeter', indicator: 'spo2', value: 85, person: 'crew-1', time: ago(3) },
    { source: 'oximeter', indicator: 'spo2', value: 97, person: 'crew-2', time: ago(2) },
    { source: 'co2-sensor', indicator: 'co2', value: 8, person: 'ship', time: ago(2) },
  ]);
  const events = [
    { v: 1, kind: 'alarm', time: ago(3), person: 'crew-1', alarm: { text: 'Tom needs help now: Blood oxygen (SpO2) 85 %.' } },
    { v: 1, kind: 'report', time: ago(3), person: 'crew-1', report: { to: 'doctor-earth', text: 'Automatic message from the Crew Health Console (written by the program, not by Tom). Urgent alarm for Tom.', topic: 'alarm' } },
    { v: 1, kind: 'report', time: ago(1), person: 'crew-1', report: { to: 'doctor-earth', text: 'Tom private letter', topic: 'letter-to-psychologist' } },
    { v: 1, kind: 'alarm', time: ago(1), person: 'ship', alarm: { text: 'Help was pressed at this computer' } },
    { v: 1, kind: 'report', time: ago(1), person: 'crew-2', report: { to: 'doctor-earth', text: 'Elly asks about her sleep' } },
  ];
  const rec = record(elly, m, { events, statusOf: () => 'shared' });
  const all = JSON.stringify({ header: rec.header, today: rec.today, sections: rec.sections });
  for (const t of ['Tom needs help', 'Urgent alarm for Tom', 'Tom private letter', 'Help was pressed', 'co2']) assert.ok(!all.includes(t), `nothing of "${t}"`);
  assert.deepEqual(section(rec, 'vitals').items.map((x) => x.value), ['97'], 'only her own blood oxygen, not his 85');
  assert.equal(section(rec, 'vitals').items.length, 1);
  assert.equal(section(rec, 'alerts').items.length, 0);
  assert.deepEqual(section(rec, 'encounters').items.map((x) => x.title), ['Message to the doctor on Earth']);
  assert.ok(!rec.sections.some((s) => s.items.some((x) => x.indicator && CELLS.find((c) => c.indicator === x.indicator).section === 'env')), 'no cabin air');
  assert.throws(() => record(SHIP, m), /ship has no medical record/);
  assert.throws(() => buildRecord({ person: elly }), /history/);
});

test('medicines, symptoms, the mind and the cycle are marked private; the rest are not', () => {
  const m = flightMachine();
  const rec = buildRecord({ person: elly, history: (id, ind) => m.history(id, ind), now: new Date(MISSION.today) });
  const priv = rec.sections.filter((s) => s.private).map((s) => s.id).sort();
  assert.deepEqual(priv, ['cycle', 'medicines', 'mind', 'symptoms']);
  assert.equal(rec.privateNote, PRIVATE_NOTE);
  for (const id of priv) assert.ok(SECTION_INFO[id].private, id);
  const msgs = buildRecord({ person: tom, history: () => [], now: NOW, events: [
    { v: 1, kind: 'report', time: ago(5), person: 'crew-1', report: { to: 'doctor-earth', text: 'I would like a private call with my psychologist or flight surgeon soon.', topic: 'talk-request' } },
    { v: 1, kind: 'report', time: ago(4), person: 'crew-1', report: { to: 'doctor-earth', text: 'Summary of my last 7 days.', topic: 'pmc' } },
  ] });
  const enc = section(msgs, 'encounters').items;
  assert.deepEqual(enc.map((x) => [x.title, x.private]), [['Summary for the private medical conference, to the doctor on Earth', false], ['Request for a private call, to Earth', true]]);
});

test('the six sections this prototype does not hold say why, and point to the planned NASA medical record row', () => {
  assert.deepEqual(NOT_HELD.map((x) => x.id), ['allergies', 'vaccinations', 'diagnoses', 'prescriptions', 'procedures', 'visits']);
  assert.equal(NOT_HELD_TEXT, 'Not in this prototype: comes from the medical record system.');
  for (const x of NOT_HELD) assert.ok(x.title && x.what && x.seenIn, x.id);
  const row = CONNECTIONS.find((c) => c.id === NOT_HELD_CONNECTION);
  assert.equal(row.status, 'planned');
  assert.match(row.name, /NASA crew medical record/);
  const rec = record(tom, machineWith());
  assert.equal(rec.notHeld.connection, row);
  assert.equal(rec.notHeld.text, NOT_HELD_TEXT);
  // The same reason for a real Inspiration4 participant: the card is the same, only the data differ.
  assert.equal(record(REAL[0], machineWith()).notHeld.items.length, 6);
});

test('alerts: a red limit, the Help key, the crew line, the automatic message, a false alarm and the all clear, newest first', () => {
  const m = machineWith([
    { source: 'manual', indicator: 'spo2', value: 85, person: 'crew-1', time: ago(10) },
    { source: 'help-key', indicator: 'camera', value: 'chest_grab_help', person: 'crew-1', time: ago(6) },
    { source: 'false-alarm', indicator: 'camera', value: 'chest_grab_ok', person: 'crew-1', time: ago(5) },
    { source: 'camera', indicator: 'camera', value: 'sleeping', person: 'crew-1', time: ago(4) },
  ]);
  const events = [
    { v: 1, kind: 'alarm', time: ago(10), person: 'crew-1', alarm: { text: 'Tom needs help now: Blood oxygen (SpO2) 85 %.' } },
    { v: 1, kind: 'report', time: ago(10), person: 'crew-1', report: { to: 'doctor-earth', text: 'Automatic message from the Crew Health Console (written by the program, not by Tom). Urgent alarm for Tom, GMT 319/02:00. Blood oxygen (SpO2) 85 %: at or below 88.', topic: 'alarm' } },
    { v: 1, kind: 'alarm', time: ago(5), person: 'crew-1', alarm: { text: 'Tom is okay: false alarm', clear: true } },
    { v: 1, kind: 'report', time: ago(5), person: 'crew-1', report: { to: 'doctor-earth', text: 'Automatic message from the Crew Health Console (written by the program, not by Tom). All clear.', topic: 'alarm-clear' } },
  ];
  const rec = record(tom, m, { events, statusOf: (e) => (e.kind === 'alarm' ? 'shared' : 'queued') });
  const items = section(rec, 'alerts').items;
  assert.ok(isNewestFirst(items));
  const tags = items.map((x) => x.tag);
  for (const t of ['Red limit', 'Help key', 'False alarm', 'Crew line', 'All clear', 'Message to the doctor']) assert.ok(tags.includes(t), t);
  assert.ok(!items.some((x) => /asleep|sleeping/i.test(x.title)), 'sleep is no alert');
  const red = items.find((x) => x.tag === 'Red limit');
  assert.equal(red.level, LEVEL.URGENT);
  assert.match(red.detail, /^At or below 88: past the urgent limit \(a draft; MedlinePlus \(NIH\)\)$/);
  assert.deepEqual(red.link, { to: 'measure', indicator: 'spo2' });
  assert.equal(items.find((x) => x.tag === 'Help key').source, 'The Help key');
  const msg = items.find((x) => x.title === 'Automatic alarm message to the doctor on Earth');
  assert.match(msg.detail, /^Sealed in the outbox for the next downlink\. Urgent alarm for Tom/);
  assert.equal(items.find((x) => x.tag === 'Crew line').detail, lineWords('shared', false));
  assert.match(lineWords('local'), /no other crew screen/);
  assert.equal(lineWords('unsent'), 'Not saved.');
  // The program's own messages are not counted twice: they stay out of "Messages to the doctor".
  assert.equal(section(rec, 'encounters').items.length, 0);
});

test('messages to the doctor: every topic gets its title, a message that was not saved shows as not sent', () => {
  const r = (topic, text = 'x', to = 'doctor-earth') => ({ to, text, ...(topic ? { topic } : {}) });
  assert.equal(messageTitle(r('pmc', 'x', 'doctor-onboard')), 'Summary for the private medical conference, to the doctor on board');
  assert.equal(messageTitle(r('letter-to-psychologist')), 'Private letter for your psychologist, to Earth');
  assert.equal(messageTitle(r('mind-checkins')), 'Your check-ins, to the doctor on Earth');
  assert.equal(messageTitle(r(null)), 'Message to the doctor on Earth');
  // A request saved before topics existed is still known by its words.
  assert.equal(messageTitle(r(null, 'I would like a private call with my psychologist or flight surgeon soon.')), 'Request for a private call, to Earth');
  const unsent = [{ event: { v: 1, kind: 'report', time: ago(1), person: 'crew-1', report: r(null, 'Please look at my data.') }, why: 'not saved: 400 (bad event)' }];
  const rec = buildRecord({ person: tom, history: () => [], now: NOW, unsent, ship: { linkToEarth: true } });
  const [item] = section(rec, 'encounters').items;
  assert.equal(item.status, 'unsent');
  assert.match(item.detail, /^Not sent: 400 \(bad event\)\. Please look at my data\.$/);
});

test('lab results: the seven real Inspiration4 draws, newest first, each value against the lab range of its row', () => {
  const p = REAL[0];
  const rec = record(p, machineWith());
  assert.deepEqual(rec.sections.map((s) => s.id), ['labs', 'documents']);
  const draws = section(rec, 'labs').items;
  assert.equal(draws.length, INSPIRATION4.timepoints.length);
  assert.ok(isNewestFirst(draws));
  assert.equal(draws[0].timepoint, 'R+194');
  assert.equal(draws[0].time, '2022-03-31T12:00:00.000Z');
  assert.equal(draws[0].title, 'Blood draw, 194 days after return');
  assert.equal(draws[draws.length - 1].title, 'Blood draw, 92 days before launch');
  const raw = INSPIRATION4.subjects[p.code].panels['R+194'];
  const values = draws[0].values;
  assert.equal(values.length, raw.filter((a) => Number.isFinite(Number(a.value))).length);
  for (const v of values) {
    const a = raw.find((x) => x.code === v.code);
    const low = a.min !== null && a.value < a.min;
    const high = a.max !== null && a.value > a.max;
    assert.equal(v.out, low ? 'below' : high ? 'above' : null, v.code);
  }
  assert.equal(draws[0].outCount, values.filter((v) => v.out).length);
  assert.deepEqual(draws[0].groups.map((g) => g.test).sort(), ['CBC', 'CMP']);
  assert.equal(draws[0].source, 'NASA OSDR, Inspiration4 (real data)');
  const fhir = section(rec, 'documents').items.find((d) => d.id === 'fhir');
  assert.ok(fhir.unavailable && /not exported as a patient record/.test(fhir.detail));
  assert.match(Object.fromEntries(rec.header.facts).Mission, /Inspiration4: launch 16 Sep 2021, return 18 Sep 2021/);
  assert.equal(rec.today.real, true);
  assert.equal(drawTime('L-3'), new Date(Date.parse(I4_DATES.launch) - 3 * DAY).toISOString());
  assert.equal(drawWords('R+1'), '1 day after return');
  // A crew member has no lab results, and the section says where the real ones are.
  const none = section(record(tom, machineWith()), 'labs');
  assert.equal(none.count, 0);
  assert.match(none.empty, /Inspiration4 crew are under their own sign-in cards/);
});

test('eyes: the OCT against NASA\'s two levels (drafts), the self-check answers, and images that wait for analysis', () => {
  const m = machineWith([
    { source: 'oct-result', indicator: 'octChange', value: 8, person: 'crew-1', time: ago(30) },
    { source: 'oct-result', indicator: 'octChange', value: 24, person: 'crew-1', time: ago(20) },
    { source: 'oct-result', indicator: 'octChange', value: 60, person: 'crew-1', time: ago(10) },
    { source: 'eye-self-check', indicator: 'visionCheck', value: 'vision changed', person: 'crew-1', time: ago(9) },
    { source: 'oct-scanner', indicator: 'octScan', value: 'scan', person: 'crew-1', time: ago(8) },
    { source: 'xray', indicator: 'xray', value: 'image', person: 'crew-1', time: ago(7) },
  ]);
  const items = section(record(tom, m), 'eyes').items;
  assert.ok(isNewestFirst(items));
  const oct = items.filter((x) => x.indicator === 'octChange');
  assert.deepEqual(oct.map((x) => x.title), ['OCT: retinal thickness change: +60 µm', 'OCT: retinal thickness change: +24 µm', 'OCT: retinal thickness change: +8 µm']);
  assert.match(oct[0].detail, /^At or above 55: past the needs-action limit \(a draft;/);
  assert.equal(oct[0].level, LEVEL.ACTION);
  assert.equal(oct[1].detail, "At or above 20 µm: NASA's earliest indication of SANS (a draft)");
  assert.equal(oct[2].detail, "Below 20 µm, NASA's earliest indication of SANS (a draft)");
  const eye = items.find((x) => x.indicator === 'visionCheck');
  assert.equal(eye.title, 'Eye self-check: Vision changed');
  assert.equal(eye.detail, 'Worth telling your flight surgeon (a draft rule).');
  for (const ind of ['octScan', 'xray']) {
    const x = items.find((y) => y.indicator === ind);
    assert.deepEqual(x.link, { to: 'complex', indicator: ind });
    assert.match(x.detail, /Needs analysis by the AI or a doctor/);
  }
});

test('the mind: the latest answers, the daily check-ins of the last days with the mind rule\'s low day, the reaction test', () => {
  const m = machineWith([
    { source: 'mood-report', indicator: 'mood', value: 'bad', person: 'crew-1', time: ago(2) },
    { source: 'attitude-report', indicator: 'attitude', value: 4, person: 'crew-1', time: ago(2) },
    { source: 'mood-report', indicator: 'mood', value: 'good', person: 'crew-1', time: ago(26) },
    { source: 'attitude-report', indicator: 'attitude', value: 3, person: 'crew-1', time: ago(50) },
    { source: 'sleep-rating', indicator: 'sleepQuality', value: 6, person: 'crew-1', time: ago(50) },
    { source: 'mood-report', indicator: 'mood', value: 'good', person: 'crew-1', time: ago(24 * 20) }, // older than 14 days
    { source: 'reaction-test', indicator: 'reaction', value: 312, person: 'crew-1', time: ago(3) },
    { source: 'weighing-report', indicator: 'weighing', value: ['home', 'sleep'], person: 'crew-1', time: ago(2) },
  ]);
  const events = [{ v: 1, kind: 'reading', time: ago(3), person: 'crew-1', reading: { source: 'reaction-test', indicator: 'reaction', value: 312, detail: { median: 312, lapses: 1, mode: 'full' } } }];
  // An answer saved before the scale ("sluggish"): the machine of this version does not take it (its scale check), so
  // it is handed in here directly; the record reads it as step 5, as src/fatigue.js does.
  const old = { time: new Date(ago(26)), value: 'sluggish', status: 'recorded', source: 'attitude-report', example: false };
  const history = (id, ind) => (ind === 'attitude' ? [...m.history(id, ind), old].sort((a, b) => a.time - b.time) : m.history(id, ind));
  const mind = section(buildRecord({ person: tom, history, events, now: NOW }), 'mind');
  const days = mind.table;
  assert.equal(days.length, 3, 'three GMT days in the last 14');
  assert.deepEqual(days.map((d) => d.low), [true, true, false]);
  assert.equal(days[1].energy, '5 of 7', 'the old "sluggish" reads as 5');
  assert.equal(days[0].energy, '4 of 7');
  assert.equal(days[2].sleep, '6 of 7');
  const row = (ind) => mind.items.find((x) => x.indicator === ind);
  assert.equal(row('mood').value, 'Bad');
  assert.equal(row('mood').verdict, 'A low day for the mind rule (a draft)');
  assert.equal(row('attitude').verdict, '');
  assert.match(row('reaction').verdict, /^Median of your last test; 1 lapse \(a response of 355 ms or more, PVT-B\)/);
  assert.match(mind.facts[0], /Missing home \(1 day\), Sleep \(1 day\)/);
  assert.equal(RECORD_RULES.mindDays, 14);
  assert.deepEqual(checkinDays({ person: tom, history: () => [], now: NOW }), []);
});

