test('words: values as the crew screen writes them, and where each reading came from', () => {
  assert.equal(valueWords('bp', { sys: 118, dia: 76 }), '118/76');
  assert.equal(valueWords('attitude', 'energetic'), 'energetic (read as 2 of 7: very lively)');
  assert.equal(valueWords('medicines', { medicine: 'melatonin', name: 'Melatonin', strength: '3 mg', amount: 1, unit: 'tablet' }), 'Melatonin 3 mg, 1 tablet');
  assert.equal(valueWords('symptoms', { symptom: 'headache', severity: 4 }), 'Headache, 4 of 10');
  assert.equal(valueWords('temp', 37.25), '37.3');
  assert.equal(valueWords('camera', 'chest_grab_help'), 'answered "need help"');
  assert.equal(topicWords(['home', 'nothing']), 'Missing home, Nothing in particular');
  assert.equal(topicWords([]), 'Nothing chosen');
  assert.equal(sourceWords({ source: 'pulse-meter', example: true }), 'Made-up example data');
  assert.equal(sourceWords({ source: 'manual' }), 'Typed in by hand');
  assert.equal(sourceWords({ source: 'ble-heart-rate' }), 'Bluetooth heart rate monitor');
  assert.equal(sourceWords({ source: 'pulse-meter' }), 'Heart rate monitor (simulated)');
  assert.equal(sourceWords({ source: 'symptom-log' }, 'symptoms'), 'Your own entry');
  assert.equal(sourceWords({ source: 'mood-report' }, 'mood'), 'Your own answer');
  assert.equal(sourceWords({ source: 'help-key' }), 'The Help key');
  assert.equal(sourceWords({ source: 'mystery-box' }), 'Source not recorded');
  const temp = CELLS.find((c) => c.indicator === 'temp');
  assert.equal(readingVerdict(temp, { value: 36.6, status: 'ok' }).text, 'Within the normal range');
  assert.equal(readingVerdict(temp, { value: 37.6, status: 'out', side: 'above' }).text, 'Above the normal range');
  const vo2 = CELLS.find((c) => c.indicator === 'vo2max');
  assert.equal(readingVerdict(vo2, { value: 20, status: 'out', side: 'below' }).text, 'Below 80% of your own pre-flight level (NASA standard)');
});

test('today and the header: the sentence and alerts the screen gives, the store in words, the counts of the person', () => {
  const m = machineWith([{ source: 'pulse-meter', indicator: 'pulse', value: 72, person: 'crew-1', time: ago(1) }]);
  const today = { sentence: 'As of 15 Nov 2026, your physical and mental condition is excellent. Keep it up, well done!', body: 0, mind: 0, ship: 0, stale: [], alerts: [] };
  const rec = buildRecord({ person: tom, history: (id, ind) => m.history(id, ind), now: NOW, today, storeKind: 'browser', mission: null });
  assert.equal(rec.today.sentence, today.sentence);
  const facts = Object.fromEntries(rec.header.facts);
  assert.equal(facts.Mission, 'No mission is set on this device.');
  assert.match(facts.Record, /in this browser only/);
  assert.equal(facts['In this record'], '1 reading; 0 messages; 0 crew lines');
  assert.match(Object.fromEntries(buildRecord({ person: tom, history: () => [], now: NOW, storeKind: 'waiting' }).header.facts).Record, /not answering/);
  const own = buildRecord({ person: tom, history: () => [], now: NOW, mission: { name: 'HERA C7', launch: '2026-11-01T12:00:00Z', landing: '2026-12-15T12:00:00Z', example: false }, flightDay: { words: 'Flight day 15' } });
  assert.equal(Object.fromEntries(own.header.facts).Mission, 'HERA C7: launch 1 Nov 2026, landing 15 Dec 2026 (GMT, set on this device). Flight day 15');
  // A note of today's levels joins the row's own verdict: the words of All measures.
  const notes = buildRecord({ person: tom, history: (id, ind) => m.history(id, ind), now: NOW, notes: { pulse: 'Common in flight' } });
  assert.equal(section(notes, 'vitals').items[0].verdict, 'Common in flight');
});

test('documents: the FHIR export without the private logs, and a copy of everything, saved on this computer', () => {
  const docs = section(record(tom, machineWith()), 'documents').items;
  assert.deepEqual(docs.map((d) => d.id), ['fhir', 'copy']);
  assert.match(docs[0].detail, /private logs \(medicines, symptoms, mind, cycle\) are not in it/);
  assert.match(docs[1].detail, /holds the private parts too/);
  assert.match(SECTION_INFO.documents.about, /Nothing is sent/);
});

test('the sources are public links, the "?" cards exist, and the screen has its key and its new fold words', async () => {
  for (const [k, s] of Object.entries(RECORD_SOURCES)) {
    assert.ok(s.name && /^https:\/\//.test(s.url), k);
  }
  assert.ok(TIPS.record && TIPS.record.lines.length >= 3);
  assert.ok(TIPS.recordmissing && /HL7 International Patient Summary/.test(TIPS.recordmissing.lines.join(' ')));
  const crew = await readFile(new URL('../src/crew.js', import.meta.url), 'utf8');
  assert.match(crew, /\['record', 'Medical record', 'user', 'Record'\]/);
  assert.ok(crew.includes("'Nothing needs your attention'") && crew.includes('`Show all ${real.length}`'), 'the fold says "Nothing needs your attention" and "Show all N"');
  assert.ok(!crew.includes('Nothing to look at'));
  const page = await readFile(new URL('../index.html', import.meta.url), 'utf8');
  assert.match(page, /id="screen-record"/);
  assert.match(page, /grid-template-columns: repeat\(5, minmax\(0, 1fr\)\)/);
  assert.match(page, /@media print/);
});

test('no long dashes in the files of this change, and the new files say who wrote them', async () => {
  const dashes = new RegExp(`[${String.fromCharCode(0x2013, 0x2014)}]`);
  for (const f of ['src/medrecord.js', 'src/record-view.js', 'src/tips.js', 'src/crew.js', 'index.html', 'tests/medrecord.test.js']) {
    const text = await readFile(new URL(`../${f}`, import.meta.url), 'utf8');
    assert.ok(!dashes.test(text), `${f} has a long dash`);
  }
  for (const f of ['src/medrecord.js', 'src/record-view.js']) {
    const text = await readFile(new URL(`../${f}`, import.meta.url), 'utf8');
    assert.match(text.slice(0, 4000), /Code generated by Claude \(Anthropic\), an AI system\./, f);
  }
});
